import importlib.util, glob, json
def load_mod(tid):
    spec=importlib.util.spec_from_file_location(tid, tid+'.py')
    m=importlib.util.module_from_spec(spec); spec.loader.exec_module(m); return m
for jf in sorted(glob.glob('task-*.json')):
